customCSS:
/* ══ PLAYBILL BUTTON ══ */

.row-button,
button.row-button {
  background: #010117 !important;       /* deep ink-blue */
  color: #f4efdf !important;            /* old script-paper */
  border: 1px solid #c8a85c !important; /* muted theatre-gold */
  border-radius: 3px !important;

  box-shadow: none !important;
  text-shadow: none !important;
  letter-spacing: 0.055em;

  transition:
    background-color 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease !important;
}

.row-button *,
button.row-button * {
  color: #f4efdf !important;
  text-shadow: none !important;
}

.row-button:hover,
button.row-button:hover {
  background: #09092b !important;       /* same blue family, slightly lifted */
  color: #fffaf0 !important;
  border-color: #e1c878 !important;
  transform: translateY(-1px) !important;
  box-shadow: none !important;
}

.row-button:active,
button.row-button:active {
  background: #00000c !important;
  color: #e8dcb8 !important;
  border-color: #a88842 !important;
  transform: translateY(0) !important;
}

.row-button:focus,
.row-button:focus-visible,
button.row-button:focus-visible {
  outline: none !important;
  box-shadow: none !important;
  border-color: #e1c878 !important;
}

/* Fade-in animation */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(50px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* affected row */
.row-row-3xpt-bg > div {
  opacity: 0;
  transform: translateY(50px);
  animation: fadeIn 0.9s ease forwards;
}

@keyframes blurIn {
  from { opacity: 0; filter: blur(10px); }
  to   { opacity: 1; filter: blur(0); }
}

.row-row-3xpt-bg > div {
  opacity: 0;
  animation: blurIn 0.9s ease forwards;
}
